import fs from "node:fs";
const repo = "acmelabs-15/design-system";
const queries: any[] = [];
function api(endpoint: string) {
  const result = Bun.spawnSync(["gh", "api", endpoint], { stdout: "pipe", stderr: "pipe" });
  let body: any;
  try { body = JSON.parse(result.stdout.toString()); } catch { body = null; }
  queries.push({ command: ["gh", "api", endpoint], exitCode: result.exitCode, stderr: result.stderr.toString(), response: body && (body.path ? { path: body.path, sha: body.sha, html_url: body.html_url, type: body.type } : body.object ? { ref: body.ref, object: body.object } : { sha: body.sha, message: body.message, html_url: body.html_url, object: body.object }) });
  return body;
}
const main = api("repos/" + repo + "/commits/main");
for (const version of ["0.3.0", "0.3.1", "0.3.2"]) {
  const relative = "notes/alignment/release-" + version + ".md";
  api("repos/" + repo + "/contents/" + relative + "?ref=main");
  api("repos/" + repo + "/contents/" + relative + "?ref=" + main.sha);
  const tag = api("repos/" + repo + "/git/ref/tags/v" + version);
  if (tag?.object?.type === "tag") api("repos/" + repo + "/git/tags/" + tag.object.sha);
}
api("repos/" + repo + "/contents/notes/analysis/book-census-config.md?ref=5ae1f7a27d90d87e7e77dad20964541146444564");
fs.writeFileSync("/private/tmp/workflow-external-remote.json", JSON.stringify({ checkedAt: new Date().toISOString(), mainSha: main.sha, queries }, null, 2) + "\n");
console.log(JSON.stringify({ mainSha: main.sha, queries: queries.map(query => ({ endpoint: query.command[2], exitCode: query.exitCode, result: query.response })) }, null, 2));

