import fs from "node:fs";
import path from "node:path";
const root = "/Users/peterkloss/Dev/ACMElabs/design-system";
const local = JSON.parse(fs.readFileSync("/private/tmp/workflow-external-local.json", "utf8"));
const checks: any[] = [];
const slug = (text: string) => text.toLowerCase().replace(/<[^>]*>/g, "").replace(/[^\p{L}\p{N}_\- ]/gu, "").replace(/ /g, "-");
for (const archive of local.archives) {
  for (const reference of [...new Set(archive.embeddedRecipeReferences.map((entry: any) => entry.reference))] as string[]) {
