    checks.push({ version: archive.version, revision: archive.sourceCommit, reference, file, anchor: anchor ?? null, sourceObjectAvailable: source.exitCode === 0, currentWorktreeTargetExists: fs.existsSync(path.join(root, file)), anchorMatched: anchor ? headings.some(heading => heading.slug === anchor) : null, ...(anchor && !headings.some(heading => heading.slug === anchor) ? { headings } : {}), immutableSourceUrl: "https://github.com/acmelabs-15/design-system/blob/" + archive.sourceCommit + "/" + reference, method: "git show verifies the source object; heading slug matching verifies fragment spelling locally. Release tag/source commit reachability is checked through GitHub API. This is not an HTTP fragment-navigation test." });
  }
}
fs.writeFileSync("/private/tmp/workflow-external-resolve.json", JSON.stringify(checks, null, 2) + "\n");
